function load(rel){ const f = path.join(root, rel); const raw = fs.readFileSync(f, 'utf8'); return { f, rel, crlf: raw.includes('\r\n'), text: raw.replace(/\r\n/g, '\n') }; }
function save(o){ fs.writeFileSync(o.f, o.crlf ? o.text.replace(/\n/g, '\r\n') : o.text); }
if (fs.existsSync(path.join(root, 'www', 'vfx.js'))){ console.log('Already applied (www/vfx.js exists). Nothing to do.'); process.exit(0); }
if (!fs.existsSync(path.join(root, 'www', 'fx.js'))){ console.log('Apply the masks / chroma key / blend patch first (tools/apply-masks-chroma-blend.js): www/fx.js is missing.'); process.exit(1); }
const problems = [], files = {};
Object.keys(EDITS).forEach(rel => {
  const o = files[rel] = load(rel);
  EDITS[rel].forEach(e => {
    if (e.op === 'rep'){
      const n = o.text.split(e.find).length - 1;
      if (n !== 1){ problems.push(e.label + ': found ' + n + ' times (need exactly 1) in ' + path.basename(rel)); return; }
      o.text = o.text.replace(e.find, () => e.replace);
    } else {
      const m = o.text.match(new RegExp(e.re, 'g'));
      if (!m || m.length !== 1){ problems.push(e.label + ': found ' + (m ? m.length : 0) + ' times (need exactly 1) in ' + path.basename(rel)); return; }
      o.text = o.text.replace(new RegExp(e.re), e.replace);
    }
  });
});
const cssFile = load('www/editor.css'); cssFile.text = cssFile.text.replace(/\s*$/, '\n') + "\n/* VFX: effects row, beat ticks, preview layers */\n.ed-clip.k-vfx{background:#a02a6e;border-color:#e06bb0}\n.ed-beat{position:absolute;bottom:0;width:1px;height:6px;background:var(--mango);opacity:.7;pointer-events:none}\n.ed-beat.bar{height:12px;opacity:1}\n.ed-fxflash{position:absolute;inset:0;background:#fff;pointer-events:none;display:none;z-index:3}\n.ed-fxgrain{position:absolute;inset:0;pointer-events:none;display:none;background-size:96px 96px;mix-blend-mode:overlay;z-index:3}\n.ed-fxbadge{position:absolute;left:8px;top:8px;padding:3px 9px;border-radius:999px;background:rgba(17,27,36,.88);color:var(--mango);font-size:12px;font-weight:650;display:none;pointer-events:none;z-index:6}\n/* ten tools no longer fit on a phone: the toolbar scrolls sideways */\n.ed-toolbar{overflow-x:auto;scrollbar-width:none;justify-content:flex-start}\n.ed-toolbar::-webkit-scrollbar{display:none}\n.ed-tool{flex:1 0 56px}\n"; files['www/editor.css'] = cssFile;
if (problems.length){
  console.log('NOTHING WAS CHANGED. These spots did not match your files:\n  - ' + problems.join('\n  - '));
  console.log('\nSend me that list (and the file names) and I will adjust.');
  process.exit(1);
}
Object.keys(files).forEach(rel => save(files[rel]));
fs.writeFileSync(path.join(root, 'www', 'vfx.js'), B.vfxJs);
fs.writeFileSync(path.join(root, 'www', 'beat.js'), B.beatJs);
fs.writeFileSync(path.join(root, 'tests', 'vfx.test.js'), B.test);
console.log('Done. Changed ' + Object.keys(files).length + ' files, added www/vfx.js, www/beat.js and tests/vfx.test.js.\nNow run:  npm test');